          },
        ],
      },
    },
    position: [880, 300],
  },
})

const yourWorkflowLogic = node({
  type: 'n8n-nodes-base.noOp',
  version: 1,
  config: {
    name: 'Your workflow logic here',
    parameters: {},
    position: [1200, 200],
  },
  output: [{}],
