export default workflow('schema-validator-usage-example', 'Schema Validator Usage Example')
  .add(webhookTrigger)
  .to(validateSchema)
  .to(ifParamsValid
    .onTrue(yourWorkflowLogic.to(returnSuccess))
    .onFalse(return400))

